<!DOCTYPE html><html lang="vi"><head><meta charset="utf-8"><title>Hóa đơn {{ $invoice->invoice_code }}</title><style>body{font-family:Arial;max-width:760px;margin:30px auto}table{width:100%;border-collapse:collapse}th,td{border:1px solid #111;padding:8px;text-align:left}.right{text-align:right}@media print{button{display:none}}</style></head><body><button onclick="window.print()">In</button><h1>HÓA ĐƠN KÝ TÚC XÁ</h1><p>Mã hóa đơn: <strong>{{ $invoice->invoice_code }}</strong></p><p>Sinh viên: {{ $invoice->contract->allocation->student->user->name ?? '—' }}</p><p>Kỳ thanh toán: {{ $invoice->billing_month }}/{{ $invoice->billing_year }}</p><table><tr><th>Khoản thu</th><th>SL</th><th>Đơn giá</th><th>Thành tiền</th></tr>@foreach($invoice->items as $item)<tr><td>{{ $item->description ?: $item->item_type }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->unit_price) }}</td><td>{{ number_format($item->amount) }}</td></tr>@endforeach<tr><th colspan="3" class="right">Tổng cộng</th><th>{{ number_format($invoice->total_amount) }} đ</th></tr></table></body></html>
